function validDependencies(p){if(!p)return false;if(p.dependencies===undefined)return true;if(!Array.isArray(p.tasks)||!Array.isArray(p.dependencies)||p.dependencies.length>1000)return false;const ids=new Set(p.tasks.map(t=>t.id)),adj=new Map(),keys=new Set();for(const e of p.dependencies){if(!e||!ids.has(e.from)||!ids.has(e.to)||e.from===e.to||keys.has(e.from+'|'+e.to))return false;keys.add(e.from+'|'+e.to);if(!adj.has(e.from))adj.set(e.from,[]);adj.get(e.from).push(e.to);}const degrees=new Map([...ids].map(id=>[id,0]));for(const targets of adj.values())for(const id of targets)degrees.set(id,degrees.get(id)+1);const queue=[...ids].filter(id=>!degrees.get(id));let seen=0;while(queue.length){const id=queue.pop();seen++;for(const next of adj.get(id)||[]){degrees.set(next,degrees.get(next)-1);if(!degrees.get(next))queue.push(next);}}return seen===ids.size;}
